/* Small UI modules; content and translations are generated by the build. */
(() => {
  const root = document.getElementById('snow-cv-portfolio');
  const config = JSON.parse(document.getElementById('snow-config').textContent);
  const message = (key, values = {}, language = root.lang) =>
    config.messages[language][key].replace(/\{(\w+)\}/g, (_, name) => values[name]);

  function initTabs() {
    const tabs = [...root.querySelectorAll('[data-tab]')];
    const panels = [...root.querySelectorAll('[role="tabpanel"]')];
    function activate(button) {
      for (const tab of tabs) {
        tab.setAttribute('aria-selected', String(tab === button));
        tab.tabIndex = tab === button ? 0 : -1;
      }
      for (const panel of panels) panel.hidden = panel.id !== button.getAttribute('aria-controls');
    }
    for (const button of tabs) {
      button.addEventListener('click', () => activate(button));
      button.addEventListener('keydown', event => {
        const current = tabs.indexOf(button);
        const next = event.key === 'ArrowRight' ? (current + 1) % tabs.length
          : event.key === 'ArrowLeft' ? (current + tabs.length - 1) % tabs.length
          : event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : null;
        if (next === null) return;
        event.preventDefault();
        activate(tabs[next]);
        tabs[next].focus();
      });
    }
  }

  function initDisclosures() {
    for (const panel of root.querySelectorAll('[role="tabpanel"]')) {
      const sections = [...panel.querySelectorAll('.fold-section')];
      for (const section of sections) {
        section.querySelector('.fold-toggle').addEventListener('click', () => {
          const expand = section.dataset.expanded !== 'true';
          for (const sibling of sections) {
            const selected = sibling === section && expand;
            sibling.dataset.expanded = String(selected);
            const button = sibling.querySelector('.fold-toggle');
            button.setAttribute('aria-expanded', String(selected));
            button.querySelector('.fold-sign').textContent = selected ? '−' : '+';
          }
        });
      }
    }
  }

  function initPublications() {
    const papers = [...root.querySelectorAll('.paper')];
    const citations = [...root.querySelectorAll('.citation')];
    function closeCitations() {
      for (const paper of papers) paper.querySelector('.cite-toggle').setAttribute('aria-expanded', 'false');
      for (const citation of citations) citation.hidden = true;
    }
    for (const paper of papers) {
      const expandButton = paper.querySelector('.paper-expand');
      expandButton.addEventListener('click', () => {
        const expand = paper.dataset.open !== 'true';
        for (const sibling of papers) {
          const open = sibling === paper && expand;
          sibling.dataset.open = String(open);
          sibling.querySelector('.paper-expand').setAttribute('aria-expanded', String(open));
          sibling.querySelector('.expand-sign').textContent = open ? '−' : '+';
        }
        closeCitations();
      });
      paper.querySelector('.cite-toggle').addEventListener('click', event => {
        const open = event.currentTarget.getAttribute('aria-expanded') !== 'true';
        closeCitations();
        event.currentTarget.setAttribute('aria-expanded', String(open));
        paper.querySelector('.citation').hidden = !open;
      });
      root.addEventListener('languagechange', () => {
        expandButton.setAttribute('aria-label', message('details', {title: paper.querySelector('.paper-name').textContent}));
      });
    }
    for (const citation of citations) {
      const format = citation.querySelector('.cite-format');
      const output = citation.querySelector('.cite-text');
      const status = citation.querySelector('.copy-status');
      function render() {
        const id = format.value === 'bibtex' ? 'snow-bib-' + citation.dataset.paper
          : 'snow-ref-' + citation.dataset.paper + '-' + root.lang;
        output.textContent = document.getElementById(id).content.textContent.trim();
        output.dataset.format = format.value;
        status.textContent = '';
      }
      format.addEventListener('change', render);
      root.addEventListener('languagechange', render);
      citation.querySelector('.copy').addEventListener('click', async () => {
        try {
          await navigator.clipboard.writeText(output.textContent.trim());
          status.textContent = message('copied');
        } catch {
          const selection = window.getSelection();
          const range = document.createRange();
          range.selectNodeContents(output);
          if (selection) { selection.removeAllRanges(); selection.addRange(range); }
          status.textContent = message('copy_failed');
        }
      });
    }
  }

  function initLanguage() {
    const nodes = [...root.querySelectorAll('[data-l]')];
    const button = document.getElementById('snow-language');
    const download = document.getElementById('snow-cv-download');
    const email = root.querySelector('.contact-email');
    const live = document.getElementById('snow-live');
    const languages = config.languages;
    function apply(code) {
      root.lang = code;
      root.dataset.language = code;
      document.documentElement.lang = code;
      const index = languages.findIndex(language => language.code === code);
      const current = languages[index];
      const next = languages[(index + 1) % languages.length];
      for (const node of nodes) {
        node.hidden = node.dataset.l !== code;
        node.setAttribute('aria-hidden', String(node.hidden));
      }
      download.href = config.pdfs[code].href;
      download.download = config.pdfs[code].filename;
      download.setAttribute('aria-label', message('download_cv'));
      download.title = message('download_cv');
      button.setAttribute('aria-label', message('current_language', {name: current.name}) + ' ' + message('switch_to', {}, next.code));
      button.title = current.name + ' · ' + message('switch_to', {}, next.code);
      email.setAttribute('aria-label', message('email', {email: config.email}));
      root.querySelector('[role="tablist"]').setAttribute('aria-label', message('portfolio'));
      root.dispatchEvent(new CustomEvent('languagechange', {detail: code}));
    }
    button.addEventListener('click', () => {
      const index = languages.findIndex(language => language.code === root.lang);
      apply(languages[(index + 1) % languages.length].code);
      live.textContent = message('switched');
    });
    apply(config.defaultLanguage);
  }

  initTabs();
  initDisclosures();
  initPublications();
  initLanguage();
})();
